        self._book(isbn)
        if isbn not in loans:
            raise ValueError("Not borrowed")
        del loans[isbn]

    def loans_of(self, member):
        loans = self._member(member)
        return sorted(loans.items(), key=lambda item: (item[1], item[0]))

